# Regenerate final M1 evidence using E/F without adjusting any accepted fit.
if(dir.exists('.local/R-library')) .libPaths(c(normalizePath('.local/R-library'),.libPaths()))
source('R/scp_calibrate.R');started<-proc.time()[['elapsed']];out<-'reports/M1-final'
rs<-readRDS(file.path(out,'calibration-results.rds'));tab<-read.csv(file.path(out,'calibration-table.csv'));s<-read.csv(file.path(out,'dataset-summary.csv'))
m<-jsonlite::read_json(file.path(out,'run-manifest.json'),simplifyVector=FALSE)
bench<-jsonlite::read_json(file.path(out,'paper-benchmarks.json'),simplifyVector=TRUE)$benchmarks
vs<-.scp_versions();vt<-paste(names(vs),vs,sep='=',collapse='; ')
footer<-function(){mtext('TMT raw intensities define missingness; accepted ratios define variance. k=1 is assumed.',side=1,outer=TRUE,line=1,cex=.65);mtext(vt,side=1,outer=TRUE,line=2.2,cex=.48)}
png(file.path(out,'variance-components.png'),width=2100,height=1250,res=180);par(mfrow=c(2,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in names(rs)){d<-rs[[n]]$tiers;v<-as.matrix(d[,c('sigma2_s','sigma2_b','sigma2_e')]);matplot(d$tier,v,type='b',pch=c(16,17,15),lty=1,col=c('#d17c00','#7954a1','#1680a1'),xlab='Accepted abundance tier',ylab='Variance (log2 squared)',main=n,ylim=c(0,max(v,na.rm=TRUE)*1.1));if(n=='brunner2022')mtext('Run noise absorbed into cell variance',side=3,line=.2,cex=.7)}
plot.new();legend('center',legend=c('Walzik whole-PBMC donor proxy','Batch','Cell residual / combined cell-run'),pch=c(16,17,15),lty=1,col=c('#d17c00','#7954a1','#1680a1'),bty='n',cex=.8);footer();dev.off()
png(file.path(out,'missingness-fit.png'),width=2100,height=1250,res=180);par(mfrow=c(2,3),mar=c(4,4,4,1),oma=c(4,0,2,0))
for(n in names(rs)){r<-rs[[n]];p<-r$missingness_proteins;plot(p$mean_log2,p$missing_fraction,pch=16,cex=.25,col='#88888866',xlab='Mean observed log2 intensity',ylab='Missing fraction',ylim=c(0,1),main=n);lines(r$curve$expected_log2,r$curve$missing_probability,col=if(length(r$manifest$flags))'#b22222' else '#1680a1',lwd=2);mtext(sprintf('Quantification slope %.3f [%.3f, %.3f]',r$missingness$slope,r$missingness$slope_low,r$missingness$slope_high),side=3,line=.2,cex=.65)}
plot.new();text(.5,.6,'Points: observed protein missingness\nCurve: registered logistic fit\nAll five series calibrated',cex=.9);footer();dev.off()
f<-function(v,d=3)format(round(v,d),nsmall=d,trim=TRUE);pct<-function(v)paste0(f(100*v,1),'%')
note<-c('# scpPower M1 closure: plausibility note (v1.1.2)','13 October 2026. Amendments E/F close all five dataset/instrument rows. Earlier stops are preserved. No variance estimate was retuned to a source paper.', '',
 sprintf('**Specht.** Raw PSM missingness %s, mean %s proteins/cell; quantification slope %s [%s, %s]. The accepted ratio assay remains %s missing with %s proteins/cell and peptide-agreement cell CV %s. The paper\'s global estimate is approximately %s missing and %s proteins/cell; its %s within-identified-peptide missingness has a different denominator. FLAG: the raw slope is weakly negative and does not support the usual abundance trend; it is retained exactly for the registered gate. The any-positive-PSM mask is earlier and more permissive than the paper\'s QC mask. The variance scale remains ratios; the predictor now measures raw abundance. [Specht](https://doi.org/10.1186/s13059-021-02267-5).',pct(s$missing_fraction[1]),f(s$mean_proteins_per_cell[1],1),f(s$quantification_slope[1]),f(s$slope_low[1]),f(s$slope_high[1]),pct(mean(rs[[1]]$proteins$missing_fraction)),f(mean(rs[[1]]$proteins$quantified_cells),1),f(s$median_cell_peptide_cv[1]),pct(bench$specht$global_missing_fraction),f(bench$specht$implied_mean_proteins_per_cell,1),pct(bench$specht$within_identified_peptide_missing/100)), '',
 sprintf('**Leduc.** Raw PSM missingness %s, mean %s proteins/cell; slope %s [%s, %s]. The ratio input remains %s missing; peptide-agreement cell CV %s versus the paper\'s QC cutoff %s. The paper reports %s proteins/cell after processing. FLAG: raw-mask completeness and coverage differ from the processed endpoint; raw protein ID groups and pre-QC PSMs do not reconstruct its final mask. Raw PSMs and ratio-based variance are explicitly separate inputs. [Leduc](https://doi.org/10.1186/s13059-022-02817-5).',pct(s$missing_fraction[2]),f(s$mean_proteins_per_cell[2],1),f(s$quantification_slope[2]),f(s$slope_low[2]),f(s$slope_high[2]),pct(mean(rs[[2]]$proteins$missing_fraction)),f(s$median_cell_peptide_cv[2]),f(bench$leduc$cv_threshold,2),f(bench$leduc$mean_proteins_per_cell,0)), '',
 sprintf('**Derks timsTOF / Q Exactive.** Missing %s / %s; proteins/cell %s / %s; within-plex completeness %s / %s. timsTOF matches the published >%s%% within-plex completeness and approximately %s proteins/cell. FLAG: Q Exactive coverage is lower than that headline. Observed linear protein CV across cells %s / %s; the paper\'s injection-repeat CV is a different quantity. Variance and curve estimates remain exactly as accepted, with file/label identity corrected. [Derks](https://doi.org/10.1038/s41587-022-01389-w).',pct(s$missing_fraction[3]),pct(s$missing_fraction[4]),f(s$mean_proteins_per_cell[3],1),f(s$mean_proteins_per_cell[4],1),pct(s$mean_within_plex_completeness[3]),pct(s$mean_within_plex_completeness[4]),f(bench$derks$within_plex_completeness,0),f(bench$derks$proteins_per_cell,0),f(s$median_observed_protein_cv[3]),f(s$median_observed_protein_cv[4])), '',
 sprintf('**Brunner.** Missing %s; proteins/cell %s (minimum %s versus the paper\'s %s cutoff, FLAG); median linear protein CV %s versus reported %s, FLAG due to differing processing/QC. After per-cell median shifts, sigma2_e is total within-HeLa cell variance, including run noise. sigma2_b is zero with the reason "absorbed into sigma2_e: one cell per run". This is the identified label-free variance, not zero noise. [Brunner](https://doi.org/10.15252/msb.202110798).',pct(s$missing_fraction[5]),f(s$mean_proteins_per_cell[5],1),f(s$minimum_proteins_per_cell[5],0),f(bench$brunner$min_proteins_per_cell,0),f(s$median_observed_protein_cv[5]),f(bench$brunner$median_cv,1)), '',
 sprintf('**Mapping and assumptions.** Raw TMT PSMs are paired by exact IDs to the accepted protein/cell population, preserving cells and variance tiers without new QC thresholds. Walzik retains %s healthy donors and %s baseline observations. Overlap counts: %s. Its proteomics is whole PBMC; immune subsets were flow cytometry, not sorted-subset proteomics. Donor composition differences are included; cell-line transfer remains an unvalidated proxy. k=%s is assumed, with sensitivity assumptions %s/%s and a two-proteome pilot standard recommended. [Walzik](https://doi.org/10.1038/s41467-025-68101-9); [Cheung, Nature Methods](https://doi.org/10.1038/s41592-020-01002-5).',m$cohort$healthy_donors,m$cohort$baseline_observations,paste(s$bulk_overlap,collapse=', '),f(1,0),f(.75,2),f(.5,1)), '',paste('Reproduction: inst/scripts/extract_tmt_psms.R, close_m1.R and report_final_m1.R; seed 20261013. Software:',vt))
# Paper benchmark constants above are verified against the publicly downloaded
# source papers by extract_paper_benchmarks.py; archive the parsed values.
# Parsed benchmarks were regenerated directly into this report directory.
# Correct ratio coverage denominator for Specht: observed counts per protein
# are summed then divided by the accepted number of cells.
ratio_mean<-sum(rs[[1]]$proteins$quantified_cells)/rs[[1]]$manifest$cells
note[4]<-sub(paste0('with ',f(mean(rs[[1]]$proteins$quantified_cells),1),' proteins/cell'),paste0('with ',f(ratio_mean,1),' proteins/cell'),note[4],fixed=TRUE)
writeLines(note,file.path(out,'plausibility-note.md'));plain<-gsub('\\[([^]]+)\\]\\([^)]*\\)','\\1',note);plain<-gsub('[`*#]','',plain)
wrapped<-unlist(lapply(plain,function(x)if(nzchar(x))strwrap(x,width=112) else ''))
pdf(file.path(out,'plausibility-note.pdf'),width=8.27,height=11.69,title='scpPower M1 closure plausibility note');par(mar=c(0,0,0,0));plot.new();plot.window(xlim=c(0,1),ylim=c(0,1));height<-min(.0148,.9/length(wrapped));for(i in seq_along(wrapped))text(.015,.985-(i-1)*height,wrapped[i],adj=c(0,1),cex=if(i==1)1 else .68);dev.off()
writeLines(c('# M1 final evidence','', 'M1 closes under frozen addendum v1.1.2. All five dataset/instrument rows are CALIBRATED. Earlier evidence is preserved in ../M1 and ../M1-resumed.', '', '[Table](calibration-table.csv), [variance](variance-components.png), [missingness](missingness-fit.png), [plausibility](plausibility-note.pdf), [manifest](run-manifest.json).','', 'TMT variance uses the accepted ratios and missingness uses raw PSM intensities. Brunner combines cell/run noise under amendment F. No fit was retuned to match a paper.'),file.path(out,'README.md'))
writeLines(c('M1 calibration closes under frozen addendum v1.1.2. All five registered dataset/instrument series are calibrated. Raw TMT reporter-intensity missingness curves are paired with the retained ratio-based variance scale; Brunner reports combined cell/run variance.','', 'The attached evidence archive contains the final table, plots, one-page plausibility note, run manifest and public-data reproduction scripts. The earlier stopped runs remain in the repository.','', 'Validation: all existing tests retained, added E/F tests passed, and R CMD check passed at the tagged commit. M2 fidelity testing and the simulator are subsequent work; scp_power and M4 are outside this release.'),file.path(out,'release-notes.md'))
m$report_generation<-list(seed=20261013,versions=as.list(vs),input_hashes=list(calibration=digest::digest(file=file.path(out,'calibration-results.rds'),algo='sha256')),wall_seconds=proc.time()[['elapsed']]-started)
m$package_version<-'0.1.0';m$output_sha256<-as.list(setNames(vapply(list.files(out,full.names=TRUE,pattern='\\.(csv|png|pdf|md)$'),function(p)digest::digest(file=p,algo='sha256'),character(1)),basename(list.files(out,full.names=TRUE,pattern='\\.(csv|png|pdf|md)$'))))
jsonlite::write_json(m,file.path(out,'run-manifest.json'),pretty=TRUE,auto_unbox=TRUE,na='null',digits=NA)
